class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        if numFriends == 1:
            return word
        size = len(word) - numFriends + 1
        best = ""
        for i in range(len(word) - size + 2):
            candidate = word[i:i + size]
            if candidate > best:
                best = candidate
        return best
